import{_ as o,o as r,c as t,a2 as a,j as l}from"./chunks/framework.BG8d4IEm.js";const f=JSON.parse('{"title":"iOS 快捷指令使用详解","description":"","frontmatter":{"tags":["工具","mac"]},"headers":[],"relativePath":"posts/2020-05-03-shortcuts.md","filePath":"posts/2020-05-03-shortcuts.md"}'),i={name:"posts/2020-05-03-shortcuts.md"};function c(s,e,d,p,h,n){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="ios-快捷指令使用详解" tabindex="-1">iOS 快捷指令使用详解 <a class="header-anchor" href="#ios-快捷指令使用详解" aria-label="Permalink to &quot;iOS 快捷指令使用详解&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>rss 订阅中看到了 <a href="https://blog.techbridge.cc/2020/04/26/ios-shortcuts-js/" target="_blank" rel="noreferrer">用 JS 玩轉 iOS shortcuts</a> 的 blog,于是学习了此工具的使用。</p><h2 id="什么是快捷指令" tabindex="-1">什么是快捷指令 <a class="header-anchor" href="#什么是快捷指令" aria-label="Permalink to &quot;什么是快捷指令&quot;">​</a></h2><p>参考 <a href="https://zh.wikipedia.org/wiki/%E5%BF%AB%E6%8D%B7%E6%8C%87%E4%BB%A4" target="_blank" rel="noreferrer">wiki</a>, 快捷指令是由阿里·温斯坦等开发者于 2014 年开发的一款工作流应用。该应用于 2017 年被苹果收购,2018 作为 iOS 12 版本的内置应用推出。</p><p>快捷指令可以将 APP 中常用的操作组合起来映射为一个快捷命令,下次直接使用快捷命令便会触发者一系列操作。参考 <a href="https://support.apple.com/zh-cn/guide/shortcuts/welcome/ios" target="_blank" rel="noreferrer">快捷命令使用手册</a> 进一步理解。</p><h2 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to &quot;快速入门&quot;">​</a></h2><blockquote><p>确保 iOS 版本 <code>≥ 12</code>,我使用 <code>13.4.1</code> 说明如何使用。</p></blockquote><p>该示例实现了,将访问的网页添加到备忘录特定页面的功能。</p><blockquote><p>开始之前确保在备忘录应用中创建了一个 <code>杂货铺的文件夹</code> 且包含 <code>收藏</code> 为开头的文件</p></blockquote>',10),l("iframe",{height:"400",width:"600",src:"//player.bilibili.com/player.html?aid=668008428&bvid=BV1Xa4y1v7LN&cid=186917494&page=1",scrolling:"no",border:"0",frameborder:"no",framespacing:"0",allowfullscreen:"true"},null,-1),a('<p>核心步骤</p><ol><li>在 iPhone 页面下拉唤起搜索,查找 <code>shortcuts</code> 打开快捷路径的应用</li><li>点击右上角创建快捷路径</li><li>将创建的快捷路径添加到共享按钮</li><li>safari 访问任意网页,点击共享按钮,触发快捷命令,会自动提取 url 并保存到备忘录收藏夹。</li></ol><p>你也可以手机端打开 <a href="https://www.icloud.com/shortcuts/276b71131ab743d6b5af6103458c8cac" target="_blank" rel="noreferrer">test 快捷路径</a></p><blockquote><p><strong>注意使用前确保 <a href="https://support.apple.com/zh-cn/guide/shortcuts/apdfeb05586f/3.5/ios/13.5#apdf9081945c" target="_blank" rel="noreferrer">允许不受信任的快捷指令</a></strong></p></blockquote><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p>根据 <a href="#快速入门">快速入门</a> 的示例,指令是由一系列独立的操作串联起来的。 阅读 <a href="https://support.apple.com/zh-cn/guide/shortcuts/apdad3cbabfc/ios" target="_blank" rel="noreferrer">快捷指令操作原理</a> 进一步理解操作流程。</p><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h3><p>例如示例中的 <code>追加到备忘录</code>,<code>显示备忘录</code> 等一系列功能。 iOS 内置了一系列内置操作方便你处理日常工作。大致分为如下几类</p><ul><li><code>App</code> 暴露了 App 的内置功能,包括邮件,短信,safari 等</li><li><code>脚本</code> 提供了一系列的控制逻辑及硬件控制功能,例如 获取电池电量,在 safari 中执行脚本 甚至包括执行执行 api,连接远程 ssh 执行命令的功能</li><li><code>媒体</code> 包含了一系列音频,视频制作 gif 的能力</li><li><code>位置</code> 包含地理位置控制,天气等接口</li><li><code>文稿</code> 包含文本处理,markdown 等常用格式的相关操作</li><li><code>共享</code> 包含共享和邮件,短信等通知功能</li><li><code>网页</code> safari 的一系列操作能力</li></ul><p>你也可以在搜索框查询所需的操作。</p><h3 id="输入和输出" tabindex="-1">输入和输出 <a class="header-anchor" href="#输入和输出" aria-label="Permalink to &quot;输入和输出&quot;">​</a></h3><p>一般的操作都会有输入,输出的概念,例如 <code>获取 url</code> 的操作会从输入中提取 url。 输出 <code>url</code> 的文本。每一个操作都包含自己的输入输出规则,通过点击操作旁边的感叹号,查询操作的帮助。其中包含一些典型的输入。</p><ul><li><code>快捷指令输入</code> 是根据当前执行快捷指令的环境提取输入,例如示例是从 safari 浏览器提取 url</li><li><code>剪切板</code> 是从剪切板提取输入</li><li><code>魔法变量</code> 是从变量中提取输入,后有详述</li></ul><h3 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h3><p>通过变量你可以将不同的操作流程串联起来,通过将中间值保存到变量,来组合 不同的输入结果。</p><p>快捷指令的重点就是利用操作结合需要处理的内容,创建一系列的操作流。 处理基本的组合,快捷指令也提供了逻辑判断,重复等逻辑操作,查看 <a href="https://support.apple.com/zh-cn/guide/shortcuts/apdb5506f698/ios" target="_blank" rel="noreferrer">高级快捷指令</a> 理解。</p><h2 id="自动化" tabindex="-1">自动化 <a class="header-anchor" href="#自动化" aria-label="Permalink to &quot;自动化&quot;">​</a></h2><p>除了创建快捷指令,你也可以采用自动化来设定自动执行的任务,概念类似 Unix 系统的定时任务。 但注意只有特定任务才会自动触发,某些任务需要手动确认后才可执行。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>若设定自动化任务的下方有 <code>运行时询问</code> 则该任务可以自动触发,否则需要手动确认后才会执行</p></div><p>可以自动触发的任务列表详见 <a href="https://support.apple.com/zh-cn/guide/shortcuts/apd602971e63/ios#apd27e876cf8" target="_blank" rel="noreferrer">自动化无需询问</a></p>',20)])])}const b=o(i,[["render",c]]);export{f as __pageData,b as default};
